import{_ as t,d as i,e as n,y as a}from"./chunks/framework.D7CAgLCq.js";const u=JSON.parse('{"title":"Fix a question without monopolizing it","description":"Preserve the original question and result while allowing a justified new question to be opened.","frontmatter":{"title":"Fix a question without monopolizing it","description":"Preserve the original question and result while allowing a justified new question to be opened."},"headers":[],"relativePath":"en/concepts/reopening-questions.md","filePath":"en/concepts/reopening-questions.md"}'),o={name:"en/concepts/reopening-questions.md"};function s(r,e,l,h,d,c){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="fix-a-question-without-monopolizing-it" tabindex="-1">Fix a question without monopolizing it <a class="header-anchor" href="#fix-a-question-without-monopolizing-it" aria-label="Permalink to &quot;Fix a question without monopolizing it&quot;">​</a></h1><p><strong>Preserve the original question and result while allowing a justified new question to be opened.</strong></p><p>Fixing the question protects an inquiry against moving its target after the outcome is known. It does not give the original question-setter permanent ownership of the goal, population, losses, or constraints. Affected and excluded positions can identify omissions and challenge the framing.</p><p>A reopening request should identify what changes and why. Its handling and reasons remain on record even if it is rejected. A new inquiry preserves the old question, evidence, and result rather than replacing a failure with a newly convenient success.</p><p>This matters especially when an apparent constraint is itself a prior decision. Asking who controls a shortage can open a relevant policy question. It cannot change what the original resource-limited test actually found.</p><p>State whether the new question replaces, runs parallel to, or refines the old one, and which existing evidence still applies. The analyst may answer both side by side. Actual changes to an institution’s indicators, eligibility, agenda, or resource allocation belong to the procedure with the corresponding authority; an analytical reframing does not itself change those rules.</p><h2 id="keep-these-judgments-separate" tabindex="-1">Keep these judgments separate <a class="header-anchor" href="#keep-these-judgments-separate" aria-label="Permalink to &quot;Keep these judgments separate&quot;">​</a></h2><div class="xk-table"><table><thead><tr><th>Preserve the test</th><th>Reopen the question</th></tr></thead><tbody><tr><td>Keep its original target, conditions, and outcome.</td><td>State a new framing and preserve the history of the change.</td></tr></tbody></table></div><h2 id="teaching-example-a-service-target-omitted-waiting-time" tabindex="-1">Teaching example: a service target omitted waiting time <a class="header-anchor" href="#teaching-example-a-service-target-omitted-waiting-time" aria-label="Permalink to &quot;Teaching example: a service target omitted waiting time&quot;">​</a></h2><p>Suppose a review fixed in advance measures completed transactions. Users then identify an omitted waiting burden. Keep the transaction result, record the challenge, and assess a new waiting-time question with suitable evidence.</p><p><strong>Assumptions:</strong> Hypothetical review; transaction counts are assumed accurate.</p><p><strong>Boundary:</strong> The omission does not automatically prove the original numerical result false.</p><h2 id="check-your-reading" tabindex="-1">Check your reading <a class="header-anchor" href="#check-your-reading" aria-label="Permalink to &quot;Check your reading&quot;">​</a></h2><p><strong>Is a disappointing outcome alone a reason to redefine success?</strong></p><p>No. A new question needs an explicit reason and its own record; the old outcome is retained.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><p>Reopening is not permission for retrospective success claims.</p></li><li><p>An affected person need not master the framework’s terminology to challenge a question.</p></li></ul><p>Read the complete <a href="/xi-kari-skill/handbook/en/theory/part-02.html#section-2-14">source section §2.14</a> and its guide. This explanation follows theory v3.0; the <a href="/xi-kari-skill/handbook/en/downloads.html">Chinese original</a> remains authoritative.</p>',18)])])}const g=t(o,[["render",s]]);export{u as __pageData,g as default};
